// Data Race 示例
var counter int
var wg sync.WaitGroup
for i := 0; i < 1000; i++ {
	wg.Add(1)
	go func() {
		defer wg.Done()
		counter++ // DATA RACE!
	}()
}
wg.Wait()
// counter 的值不确定，可能远小于 1000

// 修复方案一：atomic
var counter int64
atomic.AddInt64(&counter, 1)

// 修复方案二：Mutex
var mu sync.Mutex
mu.Lock()
counter++
mu.Unlock()

// 无锁计数器（Go 1.19+ 推荐写法）
var ops atomic.Int64

for i := 0; i < 1000; i++ {
	go func() {
		ops.Add(1)
	}()
}

// 配置热更新
var config atomic.Value
config.Store(loadConfig()) // 初始加载

// 后台定期刷新
go func() {
	for range time.Tick(time.Minute) {
		config.Store(loadConfig())
	}
}()

// 业务代码读取，无锁
cfg := config.Load().(*Config)
